from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]

    for r in range(h - 1):
        for c in range(w):
            color = g[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and g[r + 1][c2] == color:
                    rr, cc = r + 2, c2 + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if g[rr][cc] != background:
                            break
                        g[rr][cc] = color
                        rr += 1
                        cc += dc
    return g
